use vstd::prelude::*;

verus! {
    fn max_of_list(lst: &Vec<usize>) -> (result: usize)
        requires
            lst.len() > 0, // The vector must be non-empty
        ensures
            result == lst[0] || result == lst[1..].iter().max().unwrap(), // Result must be an element of the vector
            forall |x: usize| (x < lst.len() ==> lst[x] <= result) // Every element in the vector is less than or equal to the result
    {
        let mut max_value: usize = lst[0]; // Start with the first element as the maximum
        let mut idx: usize = 1; // Start from the second element

        while idx < lst.len()
            invariant
                idx <= lst.len(),
                forall |x: usize| (x < idx ==> lst[x] <= max_value), // All previous elements are less than or equal to max_value
                max_value == lst[0] || max_value == lst[1..idx].iter().max().unwrap(), // max_value is one of the elements seen so far
            decreases lst.len() - idx, // Decreases clause
        {
            if lst[idx] > max_value {
                max_value = lst[idx]; // Update max_value if current element is greater
            }
            idx = idx + 1; // Move to the next element
        }
        max_value // Return the maximum value found
    }
}

